# -*- coding: utf-8 -*-
"""LOSO streaming protocol + event-level evaluation for the frame-labeled FMCW
gesture dataset.  Block 2 (proposal_v2/28) research points 1 and 2.

Protocol discipline (each is a consequence of a measured fact, see 28 sec 4):
  * Labels are anchor + fixed 8-frame windows generated by the dataset authors'
    thresholding program, NOT variable-length human boundaries.  So we score
    ONSET and EVENT identity, never offset or duration.
  * Pre-onset leakage is strong (68.2 pct 5-way from frame 0 alone), so streams
    are built from WHOLE recordings with their real background context; we never
    splice bare 8-frame windows onto foreign background.
  * Commitments landing before the labelled onset are reported separately as
    anticipatory, neither counted as false alarms nor used to claim low latency.
  * Normalization is causal, never whole-sequence (proposal_v2/27 leakage
    lesson), AND shift-invariant in time: a fixed time constant (EMA or boxcar),
    so a gesture is scaled the same way whether it lands at frame 60 of a
    training clip or frame 15000 of a test stream.  Expanding-window norm is
    causal but not shift-invariant; it is kept behind --norm expanding as the
    isolation control.

Usage:
  python tools/fmcw_stream.py --users 3 4 5 6 7 --epochs 20
  python tools/fmcw_stream.py --users 3 4 5 6 7 --held-out-class 7
"""
import argparse
import os
import time

import numpy as np
import torch
import torch.nn as nn

BASE = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                    "fmcw_frame_labeled")
CACHE = os.path.join(BASE, "cache")
FPS = 33.0
DEV = "cuda" if torch.cuda.is_available() else "cpu"


# ---------------------------------------------------------------- data

def load_user(u, with_geom=False):
    """-> feats (n,100,32,32) float16, targets (n,100) int64, [geom (n,100,6)].
    Kept in float16 in RAM (152 MB/user instead of 409 MB); batches are cast to
    float32 on the GPU, so all 12 users fit alongside training.

    with_geom adds the MIRA feature set (radial distance / range centroid /
    Doppler centroid / two angle channels / log magnitude) from
    tools/fmcw_prep_geom.py.  Hypothesis under test (proposal_v2/28 sec 5ter):
    the labels are DEFINED by minimum radial distance, a quantity the
    antenna-averaged RD map does not carry, so adding it should help most
    across subjects."""
    z = np.load(os.path.join(CACHE, "user%d_e1_rd.npz" % u))
    f, t = z["feats"], z["targets"].astype(np.int64)
    if not with_geom:
        return f, t
    g = np.load(os.path.join(CACHE, "user%d_e1_geom.npz" % u))["geom"]
    return f, t, g.astype(np.float16)


def causal_norm(x, eps=1e-5, mode="ema", halflife=33.0):
    """Causal standardization over time.  x: (B,T,H,W).

    mode="expanding": frame t uses the mean/var of frames 1..t.  Causal and
      prefix-consistent, but NOT shift-invariant in time: the transform applied
      at frame t depends on how far t is from the last reset.  Training clips are
      100 frames and always start at a reset; a test stream resets only once at
      the beginning, so a gesture at frame 15000 is normalized by statistics over
      15000 frames -- a regime the model never saw in training.
    mode="ema" (default): exponential moving average with a fixed half-life
      (33 frames = 1 s).  Identical behaviour at any sequence length, which is
      what a deployed streaming system can actually implement.
    mode="window": causal boxcar over the last `halflife*2` frames, computed with
      a cumulative sum.  Same fixed-time-constant property as "ema" but fully
      vectorized, so long test streams do not cost a Python loop per frame.
    """
    B, T = x.shape[:2]
    v = x.reshape(B, T, -1)
    m1, m2 = v.mean(-1), (v ** 2).mean(-1)
    if mode == "expanding":
        n = torch.arange(1, T + 1, device=x.device, dtype=x.dtype).view(1, T)
        mu, ex2 = m1.cumsum(1) / n, m2.cumsum(1) / n
    elif mode == "window":
        W = int(2 * halflife)
        z = torch.zeros(B, 1, device=x.device, dtype=x.dtype)
        c1 = torch.cat([z, m1.cumsum(1)], 1)
        c2 = torch.cat([z, m2.cumsum(1)], 1)
        idx = torch.arange(1, T + 1, device=x.device)
        lo = (idx - W).clamp_min(0)
        cnt = (idx - lo).to(x.dtype).view(1, T)
        mu = (c1[:, idx] - c1[:, lo]) / cnt
        ex2 = (c2[:, idx] - c2[:, lo]) / cnt
    else:
        a = float(0.5 ** (1.0 / halflife))
        mu = torch.empty_like(m1)
        ex2 = torch.empty_like(m2)
        cur1, cur2 = m1[:, 0], m2[:, 0]
        for t in range(T):
            cur1 = a * cur1 + (1 - a) * m1[:, t]
            cur2 = a * cur2 + (1 - a) * m2[:, t]
            mu[:, t], ex2[:, t] = cur1, cur2
    var = (ex2 - mu ** 2).clamp_min(0)
    return (x - mu.view(B, T, 1, 1)) / (var.sqrt().view(B, T, 1, 1) + eps)


def events_from_labels(seq, min_len=1):
    """Run-length decode a label sequence into (class, start, end) events."""
    ev, s = [], 0
    for i in range(1, len(seq) + 1):
        if i == len(seq) or seq[i] != seq[s]:
            if seq[s] != 0 and (i - s) >= min_len:
                ev.append((int(seq[s]), s, i - 1))
            s = i
    return ev


def make_stream(feats, targets, rng, n_rec=None, geom=None):
    """Concatenate WHOLE recordings (with their real leading/trailing background)
    into one long stream."""
    idx = rng.permutation(len(feats))
    if n_rec is not None:
        idx = idx[:n_rec]
    F = feats[idx].reshape(-1, 32, 32)
    Y = targets[idx].reshape(-1)
    G = geom[idx].reshape(-1, geom.shape[-1]) if geom is not None else None
    return F, Y, events_from_labels(Y), G


# ---------------------------------------------------------------- model

class FrameEnc(nn.Module):
    def __init__(self, emb=128):
        super().__init__()
        self.c = nn.Sequential(
            nn.Conv2d(1, 16, 3, 2, 1), nn.ReLU(),
            nn.Conv2d(16, 32, 3, 2, 1), nn.ReLU(),
            nn.Conv2d(32, 64, 3, 2, 1), nn.ReLU(),
            nn.AdaptiveAvgPool2d(1), nn.Flatten(), nn.Linear(64, emb), nn.ReLU())

    def forward(self, x):
        return self.c(x)


class CausalSeg(nn.Module):
    """Per-frame causal model: CNN frame encoder + GRU + per-frame head.
    n_geom > 0 concatenates the per-frame geometric channels (radial distance
    etc.) onto the CNN embedding before the GRU."""

    def __init__(self, ncls, emb=128, hid=160, n_geom=0):
        super().__init__()
        self.enc, self.hid, self.n_geom = FrameEnc(emb), hid, n_geom
        self.gru = nn.GRU(emb + n_geom, hid, batch_first=True)
        self.head = nn.Linear(hid, ncls)

    def forward(self, x, g=None):
        B, T = x.shape[:2]
        e = self.enc(x.reshape(B * T, 1, 32, 32)).reshape(B, T, -1)
        if self.n_geom:
            e = torch.cat([e, g], dim=-1)
        h, _ = self.gru(e)
        return self.head(h)


# ---------------------------------------------------------------- eval

def match_events(pred, gt, tol=4):
    """Match predictions to ground truth by ONSET proximity (the dataset's own
    +/-4 frame convention), same class, greedy nearest, one-to-one."""
    used, tp, errs = set(), 0, []
    for c, s, _ in sorted(pred, key=lambda e: e[1]):
        best, bi = None, None
        for j, (c2, s2, _) in enumerate(gt):
            if j in used or c2 != c:
                continue
            d = abs(s - s2)
            if best is None or d < best:
                best, bi = d, j
        if bi is not None and best <= tol:
            used.add(bi)
            tp += 1
            errs.append(best)
    return tp, errs, used


def decode_stream(logits, tau, min_dwell=2, refractory=25):
    """Streaming commitment rule: commit to class c at frame t when argmax is
    non-background for min_dwell consecutive frames with softmax >= tau.  After
    a commitment stay silent for `refractory` frames (one gesture = one command)."""
    prob = torch.softmax(logits, -1).numpy()
    cls, conf = prob.argmax(-1), prob.max(-1)
    out, run, last = [], 0, -10 ** 9
    for t in range(len(cls)):
        if cls[t] != 0 and conf[t] >= tau:
            run = run + 1 if t > 0 and cls[t] == cls[t - 1] else 1
            if run >= min_dwell and t - last > refractory:
                out.append((int(cls[t]), t - min_dwell + 1, t))
                last, run = t, 0
        else:
            run = 0
    return out


def report(pred, gt, n_frames, tau, unknown_gt=None, gt_shift=0):
    """gt_shift moves every ground-truth onset by a constant number of frames.
    Used only to TEST the annotation-convention hypothesis (proposal_v2/28
    sec 5septa): users 1-8 and 9-12 place the label window on opposite sides of
    the motion anchor, about 10 frames apart, so a model trained on one group is
    systematically off when scored against the other.  Never use a non-zero
    shift in a reported result without saying so."""
    if gt_shift:
        gt = [(c, s + gt_shift, e + gt_shift) for c, s, e in gt]
        if unknown_gt is not None:
            unknown_gt = [(c, s + gt_shift, e + gt_shift)
                          for c, s, e in unknown_gt]
    return _report_core(pred, gt, n_frames, tau, unknown_gt)


def event_openset_auroc(logits, known_gt, unknown_gt, pad=4):
    """Event-level open-set score: for every ground-truth event, take the model's
    PEAK max-softmax inside the event window (padded), then AUROC between known
    and unknown events.  This is the direct analogue of the causal open-set
    signal that hit a 0.865 ceiling on UWB-Gestures (proposal_v2/26 sec 4.1), so
    the two numbers are comparable.

    Returns (auroc, n_known, n_unknown) or (nan, ...) if either side is empty."""
    prob = torch.softmax(logits, -1).numpy()
    msp = prob.max(-1)

    def peak(ev):
        out = []
        for _, s, e in ev:
            lo, hi = max(0, s - pad), min(len(msp), e + pad + 1)
            if hi > lo:
                out.append(float(msp[lo:hi].max()))
        return np.array(out)

    k, u = peak(known_gt), peak(unknown_gt)
    if len(k) == 0 or len(u) == 0:
        return float("nan"), len(k), len(u)
    # rank-based AUROC (probability a known event scores above an unknown one)
    allv = np.concatenate([k, u])
    order = allv.argsort()
    ranks = np.empty(len(allv), float)
    ranks[order] = np.arange(1, len(allv) + 1)
    # average ranks for ties
    for v in np.unique(allv):
        m = allv == v
        if m.sum() > 1:
            ranks[m] = ranks[m].mean()
    auc = (ranks[:len(k)].sum() - len(k) * (len(k) + 1) / 2) / (len(k) * len(u))
    return float(auc), len(k), len(u)


def _report_core(pred, gt, n_frames, tau, unknown_gt=None):
    tp, errs, _ = match_events(pred, gt)
    prec = tp / max(1, len(pred))
    rec = tp / max(1, len(gt))
    f1 = 2 * prec * rec / max(1e-9, prec + rec)
    minutes = n_frames / FPS / 60
    # isolation diagnostic: is a miss a true miss, or a correct-but-late commit?
    # widening the onset tolerance separates the two.
    rec_tol = {t: match_events(pred, gt, tol=t)[0] / max(1, len(gt))
               for t in (4, 8, 16, 33)}
    anticip = 0
    for c, s, _ in pred:
        for c2, s2, _ in gt:
            if c == c2 and -20 <= s - s2 < -4:
                anticip += 1
                break
    fa = (len(pred) - tp - anticip) / max(1e-9, minutes)
    row = dict(tau=tau, event_f1=f1, precision=prec, recall=rec,
               onset_mae=float(np.mean(errs)) if errs else float("nan"),
               anticipatory=anticip, false_alarm_per_min=fa,
               n_pred=len(pred), n_gt=len(gt), minutes=minutes,
               rec_t8=rec_tol[8], rec_t16=rec_tol[16], rec_t33=rec_tol[33])
    if unknown_gt is not None:
        named = 0
        for _, s, _ in pred:
            for _, s2, e2 in unknown_gt:
                if s2 - 4 <= s <= e2 + 4:
                    named += 1
                    break
        row["false_commit_rate"] = named / max(1, len(unknown_gt))
        row["n_unknown"] = len(unknown_gt)
    return row


# ---------------------------------------------------------------- run

def run_fold(users, test_user, args, rng):
    gz = args.geom
    if args.within_user:
        # Isolation control: same subject, disjoint recordings.  Everything else
        # (causal norm, decoder, metric) is identical to the LOSO path, so the
        # gap between the two is attributable to the subject change alone.
        out = load_user(test_user, gz)
        f, y = out[0], out[1]
        g = out[2] if gz else None
        cut = int(0.7 * len(f))
        perm = rng.permutation(len(f))
        tr_f, tr_y = f[perm[:cut]], y[perm[:cut]]
        te_f, te_y = f[perm[cut:]], y[perm[cut:]]
        tr_g = g[perm[:cut]] if gz else None
        te_g = g[perm[cut:]] if gz else None
    else:
        tr_f, tr_y, tr_g = [], [], []
        for u in users:
            if u == test_user:
                continue
            out = load_user(u, gz)
            tr_f.append(out[0])
            tr_y.append(out[1])
            if gz:
                tr_g.append(out[2])
        tr_f, tr_y = np.concatenate(tr_f), np.concatenate(tr_y)
        tr_g = np.concatenate(tr_g) if gz else None
        out = load_user(test_user, gz)
        te_f, te_y = out[0], out[1]
        te_g = out[2] if gz else None

    all_cls = sorted(set(np.unique(tr_y)) | set(np.unique(te_y)))
    held = args.held_out_class
    known = [c for c in all_cls if c != held]
    remap = {c: i for i, c in enumerate(known)}
    ncls = len(known)

    if held is not None:
        keep = ~(tr_y == held).any(1)
        tr_f, tr_y = tr_f[keep], tr_y[keep]
        if gz:
            tr_g = tr_g[keep]
    tr_y_m = np.vectorize(remap.get)(tr_y).astype(np.int64)

    n_geom = tr_g.shape[-1] if gz else 0
    model = CausalSeg(ncls, n_geom=n_geom).to(DEV)
    # geometric channels are standardized with TRAIN-set statistics only
    if gz:
        gmu = tr_g.reshape(-1, n_geom).astype(np.float32).mean(0)
        gsd = tr_g.reshape(-1, n_geom).astype(np.float32).std(0) + 1e-6
    opt = torch.optim.Adam(model.parameters(), lr=2e-3)
    cnt = np.bincount(tr_y_m.reshape(-1), minlength=ncls).astype(np.float64)
    w = (cnt.sum() / (ncls * np.maximum(cnt, 1))) ** 0.75
    lossf = nn.CrossEntropyLoss(
        weight=torch.tensor(w / w.mean(), dtype=torch.float32, device=DEV))

    Ft, Yt = torch.from_numpy(tr_f), torch.from_numpy(tr_y_m)
    Gt = torch.from_numpy(((tr_g.astype(np.float32) - gmu) / gsd)) if gz else None
    for ep in range(args.epochs):
        model.train()
        perm = rng.permutation(len(Ft))
        tot = 0.0
        for i in range(0, len(perm), args.batch):
            b = perm[i:i + args.batch]
            xb = causal_norm(Ft[b].to(DEV).float(), mode=args.norm)
            if args.geom_only:
                xb = torch.zeros_like(xb)
            yb = Yt[b].to(DEV)
            opt.zero_grad()
            gb = Gt[b].to(DEV) if gz else None
            out = model(xb, gb)
            loss = lossf(out.reshape(-1, ncls), yb.reshape(-1))
            loss.backward()
            opt.step()
            tot += loss.item() * len(b)
        if args.verbose:
            print("    ep%d loss=%.4f" % (ep + 1, tot / len(perm)), flush=True)

    F, Y, gt_all, G = make_stream(te_f, te_y, rng, args.stream_recs, te_g)
    known_gt = [e for e in gt_all if e[0] != held]
    unk_gt = [e for e in gt_all if e[0] == held] if held is not None else None
    gt_m = [(remap[c], s, e) for c, s, e in known_gt]

    model.eval()
    with torch.no_grad():
        x = causal_norm(torch.from_numpy(F).unsqueeze(0).to(DEV).float(),
                        mode=args.norm)[0]
        if args.geom_only:
            x = torch.zeros_like(x)
        logits = []
        h = torch.zeros(1, 1, model.hid, device=DEV)
        Gs = (torch.from_numpy(((G.astype(np.float32) - gmu) / gsd)).to(DEV)
              if gz else None)
        for t in range(0, len(x), 2000):
            e = model.enc(x[t:t + 2000].unsqueeze(1)).unsqueeze(0)
            if gz:
                e = torch.cat([e, Gs[t:t + 2000].unsqueeze(0)], dim=-1)
            o, h = model.gru(e, h)
            logits.append(model.head(o)[0].cpu())
        logits = torch.cat(logits)

    rows = [report(decode_stream(logits, tau), gt_m, len(F), tau, unk_gt,
                   getattr(args, "gt_shift", 0))
            for tau in args.taus]
    if unk_gt is not None:
        auc, nk, nu = event_openset_auroc(logits, gt_m, unk_gt)
        for r in rows:
            r["openset_auroc"] = auc
            r["n_known_ev"], r["n_unknown_ev"] = nk, nu
    return rows


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--users", type=int, nargs="+", default=[3, 4, 5, 6, 7])
    ap.add_argument("--epochs", type=int, default=20)
    ap.add_argument("--batch", type=int, default=32)
    ap.add_argument("--taus", type=float, nargs="+",
                    default=[0.5, 0.7, 0.8, 0.9, 0.95, 0.99])
    ap.add_argument("--held-out-class", type=int, default=None,
                    help="class id treated as unknown (open-set protocol)")
    ap.add_argument("--stream-recs", type=int, default=None)
    ap.add_argument("--geom", action="store_true",
                    help="add the MIRA geometric channels (needs *_geom.npz)")
    ap.add_argument("--gt-shift", type=int, default=0,
                    help="shift every ground-truth onset by N frames "
                         "(annotation-convention diagnostic only)")
    ap.add_argument("--geom-only", action="store_true",
                    help="ablation: blank the RD map so ONLY the geometric "
                         "channels carry signal (implies --geom)")
    ap.add_argument("--norm", default="ema", choices=["ema", "window", "expanding"],
                    help="causal normalization mode (see causal_norm)")
    ap.add_argument("--within-user", action="store_true",
                    help="isolation control: train/test on disjoint recordings "
                         "of the SAME subject, everything else identical")
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--verbose", action="store_true")
    ap.add_argument("--out", default="logs/fmcw_stream_results.npz")
    args = ap.parse_args()

    if args.geom_only:
        args.geom = True
    torch.manual_seed(args.seed)
    rng = np.random.default_rng(args.seed)
    msg = "LOSO over users %s" % args.users
    if args.held_out_class is not None:
        msg += ", unknown class %d" % args.held_out_class
    print(msg + ", device " + DEV)

    per_tau = {t: [] for t in args.taus}
    t0 = time.time()
    for u in args.users:
        print("  fold: test user%d (%.0fs)" % (u, time.time() - t0), flush=True)
        for row in run_fold(args.users, u, args, rng):
            per_tau[row["tau"]].append(row)

    keys = ["event_f1", "precision", "recall", "rec_t8", "rec_t16", "rec_t33",
            "onset_mae", "false_alarm_per_min", "anticipatory"]
    if args.held_out_class is not None:
        keys += ["false_commit_rate", "openset_auroc"]
    print("\n%6s " % "tau" + " ".join("%12s" % k for k in keys))
    summary = {}
    for t in args.taus:
        m = {k: float(np.nanmean([r[k] for r in per_tau[t]])) for k in keys}
        summary[t] = m
        print("%6.2f " % t + " ".join("%12.3f" % m[k] for k in keys))
    print("\nonset_mae unit: frames @33Hz (1 frame = 30.3 ms); anticipatory = "
          "commitments 5-20 frames BEFORE the labelled onset")
    os.makedirs("logs", exist_ok=True)
    np.savez(args.out, summary=summary, per_tau=per_tau, users=args.users,
             held_out=-1 if args.held_out_class is None else args.held_out_class)
    print("saved: " + args.out)


if __name__ == "__main__":
    main()
